import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage }) {
  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  return (
    <div style={{
      width: '260px',
      backgroundColor: '#15803d', // නිල් පාට වෙනුවට කොළ පාට කළා
      color: '#ffffff',
      display: 'flex',
      flexDirection: 'column',
      padding: '20px 0',
      fontFamily: 'sans-serif'
    }}>
      <div style={{ padding: '0 25px 20px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
        <h2 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0, letterSpacing: '0.5px' }}>Admin Panel</h2>
      </div>

      <nav style={{ flex: 1, marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 10px' }}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                width: '100%',
                padding: '12px 15px',
                backgroundColor: isActive ? 'rgba(0, 0, 0, 0.2)' : 'transparent',
                color: '#ffffff',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                textAlign: 'left',
                fontSize: '14px',
                fontWeight: isActive ? '600' : '500',
                transition: 'all 0.2s'
              }}
            >
              <span style={{ fontSize: '16px' }}>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          );
        })}
      </nav>
      {/* 🛑 යට තිබ්බ Logout බටන් එක මෙතනින් සම්පූර්ණයෙන්ම අයින් කළා */}
    </div>
  );
}
